// Auto-create Qdrant collections with payload indexes
const qdrantUrl = $env.QDRANT_URL || 'http://localhost:6333';
const apiKey = $env.QDRANT_API_KEY;

const headers = { 'Content-Type': 'application/json' };
if (apiKey) {
  headers['api-key'] = apiKey;
}

const collections = ['mistral_text', 'mistral_tables', 'mistral_figures'];
const results = [];

for (const collectionName of collections) {
  // Check if collection exists
  let exists = false;
  try {
    const checkResponse = await $http.get(`${qdrantUrl}/collections/${collectionName}`, { headers });
    exists = checkResponse.status === 200;
    results.push({ collection: collectionName, status: 'exists', created: false });
  } catch (error) {
    // Collection doesn't exist, create it
    const createPayload = {
      vectors: { size: 1024, distance: 'Cosine' },
      optimizers_config: { indexing_threshold: 20000 },
      replication_factor: 1
    };

    try {
      await $http.put(`${qdrantUrl}/collections/${collectionName}`, {
        headers,
        body: createPayload
      });

      // Create payload indexes
      const indexes = [
        { field_name: 'title', field_schema: 'keyword' },
        { field_name: 'type', field_schema: 'keyword' },
        { field_name: 'source', field_schema: 'keyword' },
        { field_name: 'relations.section_id', field_schema: 'keyword' },
        { field_name: 'relations.parent_section', field_schema: 'keyword' },
        { field_name: 'timestamp', field_schema: 'datetime' }
      ];

      if (collectionName.includes('table')) {
        indexes.push({ field_name: 'metadata.rows', field_schema: 'integer' });
        indexes.push({ field_name: 'metadata.columns', field_schema: 'integer' });
      } else if (collectionName.includes('figure')) {
        indexes.push({ field_name: 'metadata.format', field_schema: 'keyword' });
      }

      for (const index of indexes) {
        try {
          await $http.put(`${qdrantUrl}/collections/${collectionName}/index`, {
            headers,
            body: index
          });
        } catch (indexError) {
          // Index creation is optional, don't fail
        }
      }

      results.push({ collection: collectionName, status: 'created', created: true });
    } catch (createError) {
      results.push({ collection: collectionName, status: 'error', error: createError.message });
    }
  }
}

return { collections_status: results, ready: true };

// Enhanced Content Parser with titles, context, and relations
const mistralResponse = $input.item.json.mistral_response || $input.item.json.body?.mistral_response || '';

class ContentParser {
  constructor() {
    this.patterns = {
      markdownTable: /\|(.+)\|[\r\n]+\|[-:\s|]+\|[\r\n]+((?:\|.+\|[\r\n]+)+)/g,
      htmlTable: /<table[\s\S]*?<\/table>/gi,
      markdownImage: /!\[([^\]]*)\]\(([^)]+)\)/g,
      htmlImage: /<img[^>]+src=["']([^"']+)["'][^>]*>/gi,
      heading: /^(#{1,6})\s+(.+)$/gm
    };
  }

  buildDocumentStructure(text) {
    const sections = [];
    const parentStack = [];
    let match;
    const headingRegex = /^(#{1,6})\s+(.+)$/gm;

    while ((match = headingRegex.exec(text)) !== null) {
      const level = match[1].length;
      const section = {
        id: `section_${sections.length}`,
        level: level,
        title: match[2].trim(),
        position: match.index,
        parent_id: null,
        children: []
      };

      while (parentStack.length > 0 && parentStack[parentStack.length - 1].level >= level) {
        parentStack.pop();
      }

      if (parentStack.length > 0) {
        const parent = parentStack[parentStack.length - 1];
        section.parent_id = parent.id;
        parent.children.push(section.id);
      }

      parentStack.push(section);
      sections.push(section);
    }

    return sections;
  }

  extractTitleForElement(text, elementIndex) {
    const textBefore = text.substring(0, elementIndex).trim();
    const linesBefore = textBefore.split('\n');
    let title = null;

    for (let i = linesBefore.length - 1; i >= Math.max(0, linesBefore.length - 10); i--) {
      const line = linesBefore[i].trim();
      const headingMatch = line.match(/^(#{1,6})\s+(.+)$/);
      if (headingMatch) {
        title = headingMatch[2].trim();
        break;
      }
    }

    const contextLines = linesBefore.slice(-3);
    const context = contextLines.join('\n').trim().substring(0, 500);

    if (!title && context) {
      const sentences = context.split(/[.!?]+/);
      if (sentences.length > 0) {
        title = sentences[sentences.length - 1].trim().substring(0, 100);
      }
    }

    return { title: title || 'Untitled', context };
  }

  findSectionForElement(elementIndex, sections) {
    let currentSection = null;
    for (const section of sections) {
      if (section.position <= elementIndex) {
        currentSection = section.id;
      } else {
        break;
      }
    }
    return currentSection;
  }

  parse(text) {
    const sections = this.buildDocumentStructure(text);
    const tables = [];
    const figures = [];
    const textChunks = [];

    // Extract tables
    let match;
    while ((match = this.patterns.markdownTable.exec(text)) !== null) {
      const titleInfo = this.extractTitleForElement(text, match.index);
      const sectionId = this.findSectionForElement(match.index, sections);
      const parentSection = sections.find(s => s.id === sectionId)?.parent_id || null;

      tables.push({
        content: match[0],
        type: 'markdown',
        index: match.index,
        title: titleInfo.title,
        context: titleInfo.context,
        relations: {
          section_id: sectionId,
          parent_section: parentSection,
          references: []
        }
      });
    }

    // Reset regex
    this.patterns.htmlTable.lastIndex = 0;
    while ((match = this.patterns.htmlTable.exec(text)) !== null) {
      const titleInfo = this.extractTitleForElement(text, match.index);
      const sectionId = this.findSectionForElement(match.index, sections);
      const parentSection = sections.find(s => s.id === sectionId)?.parent_id || null;

      tables.push({
        content: match[0],
        type: 'html',
        index: match.index,
        title: titleInfo.title,
        context: titleInfo.context,
        relations: {
          section_id: sectionId,
          parent_section: parentSection,
          references: []
        }
      });
    }

    // Extract figures
    this.patterns.markdownImage.lastIndex = 0;
    while ((match = this.patterns.markdownImage.exec(text)) !== null) {
      const titleInfo = this.extractTitleForElement(text, match.index);
      const sectionId = this.findSectionForElement(match.index, sections);
      const parentSection = sections.find(s => s.id === sectionId)?.parent_id || null;

      figures.push({
        alt_text: match[1] || 'Untitled figure',
        url: match[2],
        type: 'markdown',
        index: match.index,
        title: titleInfo.title,
        context: titleInfo.context,
        relations: {
          section_id: sectionId,
          parent_section: parentSection,
          references: []
        }
      });
    }

    // Remove extracted content
    let textOnly = text;
    const removals = [
      ...tables.map(t => ({ index: t.index, length: t.content.length })),
      ...figures.map(f => ({ index: f.index, length: `![${f.alt_text}](${f.url})`.length }))
    ].sort((a, b) => b.index - a.index);

    for (const removal of removals) {
      textOnly = textOnly.substring(0, removal.index) + textOnly.substring(removal.index + removal.length);
    }

    // Extract text chunks
    const paragraphs = textOnly.split(/\n\n+/).map(p => p.trim()).filter(p => p.length > 0);
    paragraphs.forEach((paragraph, idx) => {
      const paraPosition = text.indexOf(paragraph);
      const sectionId = paraPosition !== -1 ? this.findSectionForElement(paraPosition, sections) : null;
      const parentSection = sectionId ? (sections.find(s => s.id === sectionId)?.parent_id || null) : null;

      textChunks.push({
        content: paragraph,
        chunk_index: idx,
        type: 'text',
        relations: {
          section_id: sectionId,
          parent_section: parentSection
        }
      });
    });

    return {
      text: textChunks,
      tables: tables.map((t, idx) => ({ ...t, table_index: idx })),
      figures: figures.map((f, idx) => ({ ...f, figure_index: idx })),
      sections: sections,
      metadata: {
        total_text_chunks: textChunks.length,
        total_tables: tables.length,
        total_figures: figures.length,
        total_sections: sections.length,
        timestamp: new Date().toISOString()
      }
    };
  }
}

const parser = new ContentParser();
return parser.parse(mistralResponse);

